-- ============================================
-- Appointment Service (PostgreSQL) � DB + Seed
-- ============================================
DROP DATABASE IF EXISTS appointment_service_db;
CREATE DATABASE appointment_service_db
  TEMPLATE template0
  ENCODING 'UTF8'
  LC_COLLATE 'en_US.UTF-8'
  LC_CTYPE   'en_US.UTF-8';
ALTER DATABASE appointment_service_db SET TIMEZONE TO 'Asia/Ho_Chi_Minh';
\c appointment_service_db

-- ======================
-- 1) TABLE
-- ======================
CREATE TABLE IF NOT EXISTS "Appointment" (
  "AppointmentID"   INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, -- 1..N
  "PatientID"       INT  NOT NULL,                                     -- PatientService.PatientID
  "DoctorID"        INT  NOT NULL,                                     -- EmployeeService (doctor)
  "TransactionID"   INT,                                               -- PaymentService.TransactionID
  "AppointmentDate" DATE NOT NULL,
  "TimeSlotID"      INT  NOT NULL,                                     -- EmployeeService.Shifts (e.g., 6 or 7)
  "Status"          VARCHAR(20) NOT NULL DEFAULT 'BOOKED'
                      CHECK ("Status" IN ('BOOKED','PAID','CANCELLED','COMPLETED','NO_SHOW')),
  "CreatedAt"       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "UpdatedAt"       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "DepartmentID"    INT  NOT NULL,                                     -- EmployeeService.Departments
  "WeekdayID"       INT  NOT NULL,                                     -- 1=Mon ... 7=Sun
  "RoomID"          INT
);

-- Helpful indexes
CREATE INDEX IF NOT EXISTS idx_appt_patient    ON "Appointment"("PatientID");
CREATE INDEX IF NOT EXISTS idx_appt_doctor     ON "Appointment"("DoctorID");
CREATE INDEX IF NOT EXISTS idx_appt_date       ON "Appointment"("AppointmentDate");
CREATE INDEX IF NOT EXISTS idx_appt_status     ON "Appointment"("Status");
CREATE INDEX IF NOT EXISTS idx_appt_timeslot   ON "Appointment"("TimeSlotID");

-- ======================
-- 2) SEED (5 appointments)
-- ======================
-- Assumes PaymentService created APPOINTMENT transactions with IDs 13..17
-- and ReferenceID = AppointmentID (1..5).
